-- A 127-byte varlena is one past the short-header limit (126 data bytes), so it takes a
-- 4-byte header and the next part aligns after it: `(text 127, text)` holds 2 560 characters.
-- @setup
CREATE TABLE t (a text, c text);
CREATE INDEX t_i ON t (a, c);
INSERT INTO t VALUES ('40RQry4jZoESoVXWD7jHMXQcDs4x0zWnkkDZkDN1gDaXbWPiLZhJwQFIDVMXikpSLRkO7IIRWLai2IedFsrtWMhDs9KkPgi1Xw1w8gimNXPVaWp36FdYPufeXHJLqHd', '');
-- @test
-- @profile-lock
SELECT count(*) FROM t;
